#requires -Version 7.0
# Starts the ASAA identity server (Keycloak) on 127.0.0.1:8280.
#
# identity/.env must hold KC_BOOTSTRAP_ADMIN_PASSWORD, set by the owner. The value is never printed.
# A missing or placeholder value stops the start. A value shorter than 16 characters only produces a warning
# (length check only; the value itself is never shown).
#
# The bootstrap admin is temporary: run harden-master.ps1 after the first start to create a named admin and
# replace it.
#
# Client secrets for templates-web and portfolio-admin are generated by Keycloak on first import. Read them only
# when needed in the admin console (realm asaa, Clients, the client, Credentials). Never copy them into a tracked file.

. (Join-Path $PSScriptRoot 'common.ps1')

$state = Get-StateNoSecrets
switch ($state) {
    'missing-file' { Write-Host 'identity/.env does not exist. Copy identity/.env.example to identity/.env and set KC_BOOTSTRAP_ADMIN_PASSWORD yourself.'; exit 1 }
    'missing-key'  { Write-Host 'identity/.env has no KC_BOOTSTRAP_ADMIN_PASSWORD line. Add one yourself (the value is not shown).'; exit 1 }
    'placeholder'  { Write-Host 'KC_BOOTSTRAP_ADMIN_PASSWORD is still the placeholder. Set your own value in identity/.env (the value is not shown).'; exit 1 }
    'too-short'    { Write-Host 'WARNING: KC_BOOTSTRAP_ADMIN_PASSWORD is shorter than 16 characters (length check only). Starting anyway. The bootstrap admin is temporary: run harden-master.ps1 next, which replaces it with a named admin.' }
    'ok'           { }
}

$code = Invoke-Compose 'up' '-d'
if ($code -ne 0) {
    Write-Host "docker compose up failed with exit code $code. Is Docker Desktop running?"
    exit $code
}
Write-Host 'Keycloak is starting on http://127.0.0.1:8280 (realm asaa). Run identity/scripts/status.ps1 to check it.'
if ($state -ne 'too-short') {
    Write-Host 'Next: run identity/scripts/harden-master.ps1 to create a named admin and replace the bootstrap admin.'
}
exit 0
